select date_trunc('year', signup_date) as year_start, stddev_samp(credit_limit) as credit_limit_stddev, approx_percentile(age, 0.5) as age_p50, count(*) filter (where segment = 'SMB') as smb_rows, count(*) filter (where country = 'DE') as de_rows, corr(age, credit_limit) as corr_age_credit_limit from customers group by date_trunc('year', signup_date) having de_rows < 1 order by year_start;
